public static class Evidence {
 public const int Schema=2; public static readonly JsonSerializerOptions Json=new(){PropertyNamingPolicy=JsonNamingPolicy.CamelCase,WriteIndented=true,Converters={new System.Text.Json.Serialization.JsonStringEnumConverter()}};
 public static readonly JsonSerializerOptions Jsonl=new(){PropertyNamingPolicy=JsonNamingPolicy.CamelCase,WriteIndented=false,Converters={new System.Text.Json.Serialization.JsonStringEnumConverter()}};
 public static void Atomic<T>(string p,T v){Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(p))!);var t=p+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(t,JsonSerializer.Serialize(v,Json),new UTF8Encoding(false));File.Move(t,p,true);}finally{if(File.Exists(t))File.Delete(t);}}
 public static string Hash(string p)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p)));
 public static Artifact ReadArtifact(string p){var i=new FileInfo(p);if(!i.Exists||i.Length==0)throw new InvalidDataException("Artifact is missing or empty.");return new(i.FullName,i.LastWriteTimeUtc,i.Length,Hash(p));}
}
public sealed class JsonlWriter:IDisposable { readonly FileStream f;readonly StreamWriter w;readonly Guid id;long seq;public string Path{get;}public long LastSequence=>seq;public JsonlWriter(string p,Guid i){Path=System.IO.Path.GetFullPath(p);id=i;Directory.CreateDirectory(System.IO.Path.GetDirectoryName(Path)!);f=new(Path,FileMode.CreateNew,FileAccess.Write,FileShare.Read,4096,FileOptions.WriteThrough);w=new(f,new UTF8Encoding(false)){AutoFlush=true};}public void Write(string e,string outcome,string? detail=null){w.WriteLine(JsonSerializer.Serialize(new{schemaVersion=Evidence.Schema,invocationId=id,sequence=++seq,timestampUtc=DateTimeOffset.UtcNow,@event=e,outcome,detail},Evidence.Jsonl));w.Flush();f.Flush(true);}public void Dispose()=>w.Dispose();}
public static class Sources {
 public static (IReadOnlyList<SourceItem> Items,string Hash) Inventory(string root,string source){if(!Within(root,source)||!Directory.Exists(source))throw new InvalidOperationException("Source root is invalid.");var exts=new HashSet<string>(StringComparer.OrdinalIgnoreCase){".bas",".cls",".frm"};var a=Directory.EnumerateFiles(source,"*",SearchOption.AllDirectories).Where(p=>exts.Contains(Path.GetExtension(p))).OrderBy(Path.GetFullPath,StringComparer.OrdinalIgnoreCase).Select(p=>new SourceItem(Path.GetRelativePath(root,p).Replace('\\','/'),Path.GetExtension(p).ToLowerInvariant(),new FileInfo(p).Length,Evidence.Hash(p))).ToArray();if(a.Length==0)throw new InvalidOperationException("No VBA source files were found.");var c=string.Join("\n",a.Select(i=>$"{i.RelativePath}\t{i.Extension}\t{i.Length}\t{i.Sha256}"));return(a,Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(c))));}
 public static bool Within(string p,string c){var r=Path.GetRelativePath(Path.GetFullPath(p),Path.GetFullPath(c));return r!=".."&&!r.StartsWith(".."+Path.DirectorySeparatorChar)&&!Path.IsPathRooted(r);}
 public static byte[] Sanitize(string p){var c=File.ReadAllText(p,new UTF8Encoding(false,true));var l=Regex.Split(c,"\\r?\\n").ToList();if(l.Count>0&&Regex.IsMatch(l[0],"^\\s*VERSION\\s+1\\.0\\s+CLASS",RegexOptions.IgnoreCase)){for(int i=0;i<Math.Min(6,l.Count);i++)if(Regex.IsMatch(l[i],"^\\s*End\\s*$",RegexOptions.IgnoreCase))l[i]="END";if(!l.Any(x=>x.Contains("Attribute VB_Name",StringComparison.Ordinal))){var n=l.FindIndex(x=>x.Trim().Equals("END",StringComparison.OrdinalIgnoreCase));if(n<0)throw new InvalidDataException("Class header END was not found.");l.InsertRange(n+1,[$"Attribute VB_Name = \"{Path.GetFileNameWithoutExtension(p)}\"","Attribute VB_GlobalNameSpace = False","Attribute VB_Creatable = False","Attribute VB_PredeclaredId = False","Attribute VB_Exposed = False"]);}c=string.Join("\r\n",l);}return Encoding.ASCII.GetBytes(c+Environment.NewLine);}
 public static Dictionary<string,string> Release(string p){var t=File.ReadAllText(p,Encoding.Default);var ns=new[]{"RELEASE_PRODUCT_NAME","RELEASE_PRODUCT_VERSION","RELEASE_MANIFEST_SCHEMA_VERSION","RELEASE_TEMPLATE_SCHEMA_VERSION","RELEASE_MINIMUM_SUPPORTED_VERSION","RELEASE_BUILD_DATE"};return ns.ToDictionary(n=>n,n=>{var m=Regex.Match(t,$"Private\\s+Const\\s+{n}\\s+As\\s+String\\s*=\\s*\"([^\"]+)\"",RegexOptions.IgnoreCase);return m.Success?m.Groups[1].Value:throw new InvalidDataException($"Release constant missing: {n}");});}
}
public static class Metadata { static readonly XNamespace Cp="http://schemas.openxmlformats.org/officeDocument/2006/custom-properties",Vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes";public static XDocument Properties(IReadOnlyDictionary<string,string>r,string b,string t){var v=new[]{("Product Name",r["RELEASE_PRODUCT_NAME"]),("Product Version",r["RELEASE_PRODUCT_VERSION"]),("Build Version",b),("Release Type",t),("Manifest Schema Version",r["RELEASE_MANIFEST_SCHEMA_VERSION"]),("Template Schema Version",r["RELEASE_TEMPLATE_SCHEMA_VERSION"]),("Minimum Supported Version",r["RELEASE_MINIMUM_SUPPORTED_VERSION"]),("Build Date",r["RELEASE_BUILD_DATE"])};return new(new XDeclaration("1.0","UTF-8","yes"),new XElement(Cp+"Properties",new XAttribute(XNamespace.Xmlns+"vt",Vt),v.Select((x,i)=>new XElement(Cp+"property",new XAttribute("fmtid","{D5CDD505-2E9C-101B-9397-08002B2CF9AE}"),new XAttribute("pid",i+2),new XAttribute("name",x.Item1),new XElement(Vt+"lpwstr",x.Item2)))));}public static void Update(string p,IReadOnlyDictionary<string,string>r,string b,string t){using var z=ZipFile.Open(p,ZipArchiveMode.Update);Write(z,"docProps/custom.xml",Properties(r,b,t).ToString(SaveOptions.DisableFormatting));Ensure(z,"[Content_Types].xml","http://schemas.openxmlformats.org/package/2006/content-types","Override","PartName","/docProps/custom.xml",new(){{"ContentType","application/vnd.openxmlformats-officedocument.custom-properties+xml"}});Ensure(z,"_rels/.rels","http://schemas.openxmlformats.org/package/2006/relationships","Relationship","Type","http://schemas.openxmlformats.org/officeDocument/2006/relationships/custom-properties",new(){{"Id","rIdCustomDocProps"},{"Target","docProps/custom.xml"}});}static void Ensure(ZipArchive z,string n,string ns,string e,string k,string v,Dictionary<string,string>a){var q=z.GetEntry(n)??throw new InvalidDataException($"Required OOXML part missing: {n}");XDocument d;using(var s=q.Open())d=XDocument.Load(s);XNamespace x=ns;if(!d.Root!.Elements(x+e).Any(y=>(string?)y.Attribute(k)==v)){var y=new XElement(x+e,new XAttribute(k,v));foreach(var i in a)y.Add(new XAttribute(i.Key,i.Value));d.Root.Add(y);}Write(z,n,d.ToString(SaveOptions.DisableFormatting));}static void Write(ZipArchive z,string n,string v){z.GetEntry(n)?.Delete();var e=z.CreateEntry(n);using var w=new StreamWriter(e.Open(),new UTF8Encoding(false));w.Write(v);}}
public static class ProcessIdentity { public static bool TerminationEligible(bool d,bool c,bool g,bool l,bool s,bool i)=>d&&c&&g&&l&&s&&i;}
public static class Publication { public static Artifact Publish(string c,string t){c=Path.GetFullPath(c);t=Path.GetFullPath(t);if(!string.Equals(Path.GetDirectoryName(c),Path.GetDirectoryName(t),StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Publication candidate must be in final directory.");Directory.CreateDirectory(Path.GetDirectoryName(t)!);if(!File.Exists(t))File.Move(c,t,false);else{var b=t+"."+Guid.NewGuid().ToString("N")+".bak";try{File.Replace(c,t,b,true);}finally{if(File.Exists(b))File.Delete(b);}}return Evidence.ReadArtifact(t);}}

sealed class ExcelSession:IDisposable { readonly ExcelOwnershipLease ownership;readonly LifecycleJournal journal;readonly Guid invocationId;dynamic? book,project;public Ownership? Identity=>ownership.Identity;public ResidualState Residual=>ownership.ResidualState;public bool Clean=>ownership.CleanupCompleted;public ExcelSession(LifecycleJournal j,Guid i){journal=j;invocationId=i;ownership=new(j,i);}
 public void Start(string sentinel){ownership.Start(sentinel);var root=Path.GetDirectoryName(Path.GetFullPath(sentinel))!;var ownershipRecorded=DateTimeOffset.UtcNow;var ownershipConfirmation=WriteConfirmed(Path.Combine(root,$"{invocationId:D}.ownership-validation.json"),Path.Combine(root,$"{invocationId:D}.ownership-persisted.json"),"OwnershipValidation",ownershipRecorded,new{schemaVersion=4,invocationId,artifactKind="OwnershipValidation",activationProcessIdentity=ownership.ActivationProcessIdentity,applicationProcessIdentity=ownership.ApplicationProcessIdentity,comparisonResults=ownership.ApplicationIdentityValidation,recordedUtc=ownershipRecorded});ownership.ConfirmOwnershipEvidencePersisted(ownershipConfirmation);var topology=ownership.ObserveCleanupTopology();var topologyRecorded=DateTimeOffset.UtcNow;var topologyConfirmation=WriteConfirmed(Path.Combine(root,$"{invocationId:D}.cleanup-topology.json"),Path.Combine(root,$"{invocationId:D}.cleanup-topology-persisted.json"),"CleanupTopology",topologyRecorded,new{schemaVersion=4,invocationId,artifactKind="CleanupTopology",activationProcessIdentity=ownership.ActivationProcessIdentity,applicationProcessIdentity=ownership.ApplicationProcessIdentity,activationProcessReobservation=ownership.ActivationProcessReobservation,applicationProcessReobservation=ownership.ApplicationProcessReobservation,validation=topology,recordedUtc=topologyRecorded});if(!topology.AggregateMatch)throw new InvalidOperationException("Excel cleanup topology mismatch.");ownership.ConfirmCleanupTopologyEvidencePersisted(topologyConfirmation);book=ownership.Session.Workbook??throw new InvalidOperationException("Workbook unavailable.");project=book.VBProject;}
 EvidencePersistenceConfirmation WriteConfirmed<T>(string target,string confirmation,string kind,DateTimeOffset recorded,T value){var bytes=Encoding.UTF8.GetBytes(JsonSerializer.Serialize(value,Evidence.Jsonl));using(var file=new FileStream(target,FileMode.CreateNew,FileAccess.Write,FileShare.Read,4096,FileOptions.WriteThrough)){file.Write(bytes);file.Flush(true);}var readback=File.ReadAllBytes(target);if(!bytes.SequenceEqual(readback))throw new InvalidDataException("Ownership evidence readback mismatch.");var hash=Convert.ToHexString(SHA256.HashData(readback));var confirmed=DateTimeOffset.UtcNow;var record=new{schemaVersion=4,invocationId,artifactKind=kind+"PersistenceConfirmation",targetArtifactFileName=Path.GetFileName(target),byteLength=readback.LongLength,sha256=hash,targetRecordedUtc=recorded,recordedUtc=confirmed};var confirmationBytes=Encoding.UTF8.GetBytes(JsonSerializer.Serialize(record,Evidence.Jsonl));using(var file=new FileStream(confirmation,FileMode.CreateNew,FileAccess.Write,FileShare.Read,4096,FileOptions.WriteThrough)){file.Write(confirmationBytes);file.Flush(true);}if(!confirmationBytes.SequenceEqual(File.ReadAllBytes(confirmation)))throw new InvalidDataException("Ownership confirmation readback mismatch.");return new(invocationId,kind,Path.GetFullPath(target),readback.LongLength,hash,recorded,confirmed);}
 public void PrepareWorksheet(){var s=book?.Worksheets??throw new InvalidOperationException("Workbook unavailable.");if((int)s.Count<1)throw new InvalidOperationException("Workbook has no worksheet.");while((int)s.Count>1)s.Item((int)s.Count).Delete();if((int)s.Count!=1||!(bool)s.Item(1).Visible||(int)s.Item(1).UsedRange.Count!=1||s.Item(1).UsedRange.Value2 is not null)throw new InvalidOperationException("Expected one visible blank workbook-created worksheet.");}
 public void Begin()=>journal.Record("ExcelOperationStarted",Identity);public void Import(string p){if(project is null)throw new InvalidOperationException("Excel VBA project is unavailable.");project.VBComponents.Import(p);}public void Save(string p){PrepareWorksheet();if(book is null)throw new InvalidOperationException("Excel workbook is unavailable.");book.SaveAs(p,55);}
 public void Dispose(){if(project is not null&&Marshal.IsComObject(project))Marshal.FinalReleaseComObject(project);project=null;book=null;ownership.Dispose();}}

public static class Transaction { public static Result Execute(Request q,JsonlWriter log){Validate(q);var j=new LifecycleJournal(q.LifecyclePath,q.InvocationId);j.Record("InvocationStarted");var inv=Sources.Inventory(q.RepositoryRoot,q.SourceRoot);var rel=Sources.Release(Path.Combine(q.SourceRoot,"Application","AppReleaseInfo.bas"));var work=Path.Combine(Path.GetTempPath(),"vmf-build",q.InvocationId.ToString("N"));var prep=Path.Combine(work,"source");var output=Path.GetFullPath(q.OutputPath);Directory.CreateDirectory(prep);Directory.CreateDirectory(Path.GetDirectoryName(output)!);var candidate=Path.Combine(Path.GetDirectoryName(output)!,$".{Path.GetFileName(output)}.{q.InvocationId:N}.candidate");var sentinel=Path.Combine(work,$"sentinel-{q.InvocationId:N}.xlsx");ExcelSession? s=null;int count=0;try{s=new(j,q.InvocationId);s.Start(sentinel);s.PrepareWorksheet();s.Begin();foreach(var item in inv.Items){var src=Path.Combine(q.RepositoryRoot,item.RelativePath.Replace('/',Path.DirectorySeparatorChar));var import=src;if(item.Extension!=".frm"){import=Path.Combine(prep,$"{count:D4}-{Path.GetFileName(src)}");File.WriteAllBytes(import,Sources.Sanitize(src));}s.Import(import);count++;}var built=Path.Combine(work,"Build.xlam");s.Save(built);Metadata.Update(built,rel,q.BuildVersion,q.ReleaseType);File.Move(built,candidate,false);s.Dispose();var own=s.Identity;var res=s.Residual;s=null;if(DateTimeOffset.UtcNow>q.DeadlineUtc)throw new TimeoutException("Publication prohibited after deadline.");var final=Publication.Publish(candidate,output);j.Record("InvocationSucceeded",own);log.Write("ArtifactPublished","Success",$"path={final.Path};length={final.Length};sha256={final.Sha256}");return new(Evidence.Schema,q.InvocationId,true,"None",null,q.StartedUtc,DateTimeOffset.UtcNow,q,Path.GetFullPath(q.RepositoryRoot),inv.Hash,inv.Items,count,final,true,$"{Environment.ProcessPath}|{RuntimeInformation.FrameworkDescription}",own,j.State,true,res,log.Path,log.LastSequence,[],true);}catch{try{s?.Dispose();}catch{}try{if(j.State!="InvocationFailed"&&j.State!="InvocationSucceeded")j.Record("InvocationFailed",s?.Identity);}catch{}throw;}finally{if(File.Exists(candidate))File.Delete(candidate);if(Directory.Exists(prep))Directory.Delete(prep,true);if(File.Exists(sentinel))File.Delete(sentinel);var transientBuild=Path.Combine(work,"Build.xlam");if(File.Exists(transientBuild))File.Delete(transientBuild);}}
 public static void Validate(Request q){if(q.SchemaVersion!=Evidence.Schema||q.InvocationId==Guid.Empty)throw new ArgumentException("Invalid schema or identity.");if(DateTimeOffset.UtcNow>q.DeadlineUtc||q.DeadlineUtc<=q.StartedUtc||q.DeadlineUtc-q.StartedUtc>TimeSpan.FromSeconds(121))throw new TimeoutException("Invalid deadline.");var root=Path.GetFullPath(q.RepositoryRoot);if(!File.Exists(Path.Combine(root,".vmf-root")))throw new ArgumentException("Repository marker missing.");if(!Sources.Within(root,q.SourceRoot)||string.IsNullOrWhiteSpace(q.BuildVersion)||string.IsNullOrWhiteSpace(q.ReleaseType)||!Path.IsPathFullyQualified(q.OutputPath))throw new ArgumentException("Invalid build arguments.");}}
public static class Program { [STAThread] public static int Main(string[] args){if(args.Length!=2||args[0]!="--request"){Console.Error.WriteLine("Usage: Vmf.Build.Host --request <json>");return 1;}Request? q=null;JsonlWriter? log=null;Result r;try{q=JsonSerializer.Deserialize<Request>(File.ReadAllText(Path.GetFullPath(args[1])),Evidence.Json)??throw new InvalidDataException("Empty request.");log=new(q.LogPath,q.InvocationId);log.Write("InvocationStarted","Success");r=Transaction.Execute(q,log);}catch(Exception e){try{log?.Write("InvocationFailed","Failure",e.GetType().Name+": "+e.Message);}catch(Exception x){Console.Error.WriteLine("FatalLogFailure: "+x.Message);return 1;}Ownership? o=null;var rs=ResidualState.NotApplicable;if(q is not null&&File.Exists(q.LifecyclePath))try{var es=LifecycleJournal.Validate(q.LifecyclePath,q.InvocationId);o=es.LastOrDefault(x=>x.Ownership is not null)?.Ownership;if(o is not null)rs=ResidualState.CheckFailed;}catch{rs=ResidualState.CheckFailed;}r=new(Evidence.Schema,q?.InvocationId??Guid.Empty,false,e.GetType().Name,e.Message,q?.StartedUtc??DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,q,q?.RepositoryRoot??"","",[],0,null,false,Environment.ProcessPath??"unknown",o,"InvocationFailed",false,rs,log?.Path,log?.LastSequence??0,[],true);}finally{log?.Dispose();}try{if(q is null)throw new InvalidDataException("No correlated result path.");Evidence.Atomic(q.ResultPath,r);return r.Success?0:1;}catch(Exception e){Console.Error.WriteLine("ResultWriteFailure: "+e.Message);return 1;}}}
